/* CASE 02 唯一流程來源：中途資料只存在 runtime，完成案件才寫入共用完成紀錄。 */
(function(){
  const evidence={crop:{label:'📷 作物現場照片',detail:'拍攝田間種植作物'},pest:{label:'📷 受損葉片照片',detail:'拍攝葉片受損情形'},ratio:{label:'📄 受損比例計算',detail:'320㎡ ÷ 1,000㎡ × 100＝32%'}};
  const fieldItems={crop:{title:'現場調查｜作物',image:'case2_bokchoy_closeup.png',body:'現場種植作物：小白菜<br>與申請書記載的作物相符。',action:'拍照存證'},pest:{title:'現場調查｜受損葉片',image:'case2_pest_damage_closeup.png',body:'葉片出現明顯啃食孔洞。<br>現場並發現害蟲。',action:'拍照存證'},sign:{title:'田區資料',body:'作物：小白菜<br><b>種植面積：1,000㎡</b>',action:'記錄資料'},measure:{title:'現場測量紀錄',body:'<div class="measure-map"><i></i></div><b>受損面積：320㎡</b>',action:'記錄資料'}};
  const areas=[{id:'crop',x:17,y:48,label:'● 查看作物'},{id:'pest',x:38,y:52,label:'● 查看受損葉片'},{id:'sign',x:62,y:41,label:'● 查看田區資料'},{id:'measure',x:84,y:48,label:'● 查看測量結果'}];
  const facts=()=>s.case2Facts||(s.case2Facts={crop:false,pest:false,sign:false,measure:false,ratio:false});
  const matches=()=>s.case2Matched||(s.case2Matched={crop:false,pest:false,ratio:false});
  const runtime=()=>s.case2Runtime||(s.case2Runtime={farmOffset:0,key:false,card:false,reviewTarget:null,reviewBusy:false});
  const clearModal=()=>document.querySelectorAll('#modal').forEach(node=>node.remove());
  const showModal=(html,{dismissible=false}={})=>{clearModal();app.insertAdjacentHTML('beforeend','<section class="panel" id="modal">'+(dismissible?'<button class="close" onclick="c2CloseModal()">×</button>':'')+html+'</section>')};
  window.c2CloseModal=clearModal;
  const recordNames=()=>Object.keys(fieldItems).filter(id=>facts()[id]);
  const allFieldEvidenceRecorded=()=>{const f=facts();return f.crop&&f.pest&&f.sign&&f.measure&&f.ratio};

  function drawFarm(){
    const r=runtime(),labels=areas.map(a=>'<button type="button" class="farm-clue '+a.id+'" data-evidence="'+a.id+'" style="left:'+a.x+'%;top:'+a.y+'%"><span class="farm-clue-text">'+a.label+'</span></button>').join('');
    app.innerHTML='<section class="farm c2-farm c2-input-scene"><header class="farm-top"><div><b>農田現場調查</b><br><small>確認申請書上的情況是否屬實。</small><small class="pan-hint">按住畫面左右滑動，查看整片農田。</small></div></header>'+(recordNames().length?'<button class="fieldfile c2-records" onclick="c2File()" aria-label="調查紀錄">📁</button>':'')+'<div class="farm-viewport" id="farmViewport"><div class="farm-world" id="farmWorld">'+labels+'</div></div><div class="pan-hud">‹　按住畫面左右滑動查看農田　›</div>'+(allFieldEvidenceRecorded()?'<button class="end-field" onclick="c2EndField()">結束現場調查</button>':'')+'</section>';
    const viewport=document.querySelector('#farmViewport'),world=document.querySelector('#farmWorld');let down=false,dragged=false,startX=0,startY=0,startOffset=r.farmOffset,active=null;
    const clamp=value=>Math.max(-(world.offsetWidth-viewport.offsetWidth),Math.min(0,value));const draw=()=>world.style.transform='translate3d('+r.farmOffset+'px,0,0)';draw();
    /* 可見文字框是唯一的調查按鈕。拖曳與輕點由同一個 viewport 判斷，
       避免按鈕自行 capture pointer 後讓手機上的 pointerup 消失。 */
    viewport.addEventListener('pointerdown',event=>{down=true;dragged=false;startX=event.clientX;startY=event.clientY;startOffset=r.farmOffset;active=event.target.closest('.farm-clue')?.dataset.evidence||null;viewport.setPointerCapture(event.pointerId)});
    viewport.addEventListener('pointermove',event=>{if(!down)return;const dx=event.clientX-startX,dy=event.clientY-startY;if(Math.hypot(dx,dy)>9)dragged=true;if(dragged){event.preventDefault();r.farmOffset=clamp(startOffset+dx);draw();document.querySelector('.pan-hint')?.classList.add('fade')}});
    viewport.addEventListener('pointerup',event=>{if(!down)return;const clue=active;down=false;try{if(viewport.hasPointerCapture(event.pointerId))viewport.releasePointerCapture(event.pointerId)}catch{}active=null;if(!dragged&&clue){console.log('FARM CLUE CLICK',clue);window.c2FieldGet(clue)}});
    viewport.addEventListener('pointercancel',()=>{down=false;active=null});
  }
  window.case2Start=function(){s.case2=[];s.case2Facts={crop:false,pest:false,sign:false,measure:false,ratio:false};s.case2Matched={crop:false,pest:false,ratio:false};s.case2Runtime={farmOffset:0,key:false,card:false};showModal('<h2>案件二｜農作物災害補助申請案</h2><p>本案人物、事件及補助規定均為教學目的設計，非真實案件。</p><p>陳○○申請農作物災害補助。</p><p>申請書記載：<br>作物：小白菜<br>申請事由：病蟲害造成農作物損失</p><h3>教學虛構法規</h3><p>《農作物災害補助辦法》第8條【虛構】</p><p>「農作物因病蟲害受損，且損害面積達種植面積百分之二十以上者，農民得申請災害補助。」</p><p>申請書上的情況是否符合補助規定？<br>到現場確認事實。</p><button class="primary" onclick="c2StartFarm()">前往農田</button>')};
  window.c2StartFarm=function(){clearModal();drawFarm()};
  window.c2FieldGet=function(id){const item=fieldItems[id],image=item.image?'<img class="c2-closeup" src="assets/'+item.image+'" alt="'+item.title+'">':'';showModal('<h2>'+item.title+'</h2>'+image+'<p>'+item.body+'</p><button class="primary" onclick="c2SaveFact(\''+id+'\')">'+item.action+'</button>',{dismissible:true})};
  window.c2SaveFact=function(id){const f=facts();f[id]=true;clearModal();if(f.sign&&f.measure&&!f.ratio){window.c2Ratio();return}drawFarm()};
  window.c2Ratio=function(){showModal('<h2>計算受損比例</h2><p>種植面積：1,000㎡<br>受損面積：320㎡</p><p>320 ÷ 1,000 × 100 ＝？</p>'+['12%','20%','32%','68%'].map(v=>'<button class="choice" onclick="'+(v==='32%'?'c2RatioGood()':'c2RatioWrong()')+'">'+v+'</button>').join(''))};
  window.c2RatioWrong=function(){showModal('<p>再看看：要用「受損面積 ÷ 種植面積」。</p><button class="primary" onclick="c2Ratio()">再算一次</button>')};window.c2RatioGood=function(){facts().ratio=true;showModal('<h2>計算完成</h2><p>受損面積占種植面積：32%。</p><button class="primary" onclick="c2ReturnFarm()">返回農田</button>')};window.c2ReturnFarm=function(){clearModal();drawFarm()};
  window.c2File=function(){const f=facts(),items=Object.keys(fieldItems).filter(id=>f[id]);showModal('<h2>調查紀錄</h2>'+items.map(id=>'<button class="choice" onclick="c2RecordView(\''+id+'\')">'+(id==='crop'?evidence.crop.label:id==='pest'?evidence.pest.label:id==='sign'?'📄 田區資料':'📄 測量資料')+'</button>').join(''),{dismissible:true})};
  window.c2RecordView=function(id){const item=fieldItems[id],image=item.image?'<img class="c2-closeup" src="assets/'+item.image+'" alt="'+item.title+'">':'';showModal('<h2>'+item.title+'</h2>'+image+'<p>'+item.body+'</p><button class="primary" onclick="c2File()">返回調查紀錄</button>',{dismissible:true})};
  window.c2EndField=function(){if(!allFieldEvidenceRecorded()){clearModal();drawFarm();return}showModal('<h2>結束現場調查？</h2><p>你可以先回審查室整理目前取得的資料。<br>如果資料不足，之後仍可返回現場。</p><button class="choice" onclick="c2ReturnFarm()">繼續調查</button><button class="primary" onclick="c2Review()">返回審查室</button>')};

  window.c2Review=function(){const r=runtime(),m=matches();r.reviewTarget=null;r.reviewBusy=false;showModal('<h2>審查紀錄</h2><p>點選問題，再選擇相符的證據。</p><button class="choice" onclick="c2Pick(\'crop\')">是否為農作物？<br><small>'+(m.crop?'✓ 已夾入：作物現場照片':'尚未選擇證據')+'</small></button><button class="choice" onclick="c2Pick(\'pest\')">是否因病蟲害受損？<br><small>'+(m.pest?'✓ 已夾入：受損葉片照片':'尚未選擇證據')+'</small></button><button class="choice" onclick="c2Pick(\'ratio\')">損害是否達20%以上？<br><small>'+(m.ratio?'✓ 已夾入：受損比例32%':'尚未選擇證據')+'</small></button>')};
  window.c2Pick=function(target){const r=runtime();if(!Object.hasOwn(evidence,target)||r.reviewBusy)return;r.reviewTarget=target;r.reviewBusy=false;showModal('<h2>選擇證據</h2>'+Object.entries(evidence).map(([id,item])=>'<button type="button" class="choice" onclick="c2Choose(\''+target+'\',\''+id+'\')">'+item.label+'<br><small>'+item.detail+'</small></button>').join(''))};
  window.c2Choose=function(target,pick){const r=runtime();if(r.reviewBusy||r.reviewTarget!==target)return;r.reviewBusy=true;if(target!==pick){showModal('<p>這份資料還不能直接回答這個問題。</p><button class="primary" onclick="c2Pick(\''+target+'\')">再選一次</button>');return}matches()[target]=true;r.reviewTarget=null;r.reviewBusy=false;if(Object.values(matches()).every(Boolean)){showModal('<p>依目前調查所得事實，符合第8條所定補助要件。</p><button class="primary" onclick="c2Decision()">作成決定</button>');return}window.c2Review()};
  window.c2Decision=function(){showModal('<h2>審查決定</h2><p>依目前調查所得事實，符合第8條所定補助要件。</p><button class="choice" onclick="c2DecisionRetry()">不予核准</button><button class="choice" onclick="c2Approve()">核准補助</button>')};window.c2DecisionRetry=function(){showModal('<p>請再依目前已整理的調查事實作成決定。</p><button class="primary" onclick="c2Decision()">返回決定</button>')};window.c2Approve=function(){showModal('<h2>請蓋章</h2><p>審查決定已作成。</p><button class="primary" onclick="c2Message()">咚・核准</button>')};
  window.c2Message=function(){showModal('<h2>案件即將闔上……</h2><p>審查決定已作成。</p><p>桌上的手機震動。</p><p>📱 未知寄件者</p><p>「先別結案。」</p><p>「看看農舍後面的監視器。」</p><button class="primary" onclick="c2Msg2()">返回現場</button>')};window.c2Msg2=function(){clearModal();drawExterior()};

  const cameraFrame=(status,mode='empty')=>'<div class="camera-screen '+(mode==='empty'?'camera-empty':'')+'"><div><b>CAM 01</b><span>'+(mode==='empty'?'':'02:13')+'</span></div><div class="camera-feed">'+(mode==='empty'?'<b>NO STORAGE</b>':'錄影資料已載入')+'</div><small>'+status+'</small></div>';
  function drawExterior(){const r=runtime();app.innerHTML='<section class="shed-exterior"><header class="top"><div><b>傍晚・再次調查</b><br><small>有人提醒你：<br>「看看農舍後面的監視器。」</small></div></header>'+(r.card?'':'<button type="button" class="shed-camera-hot" onclick="c2CameraEmpty()" aria-label="查看農舍外牆監視器"><span>● 查看監視器</span></button>')+'</section>';if(r.card)window.c2InsertCard()}
  window.c2CameraEmpty=function(){showModal('<h2>農舍外牆監視器</h2>'+cameraFrame('無法播放')+'<p>監視器無法播放。</p><p>記憶卡槽是空的。</p><button class="primary" onclick="c2CameraSlot()">檢查記憶卡槽</button>')};window.c2CameraSlot=function(){showModal('<p>記憶卡不在監視器裡。</p><p>也許被收進農舍了。</p><button class="primary" onclick="c2ShedSearch()">進入農舍尋找</button>')};
  window.c2ShedSearch=function(){clearModal();const r=runtime();app.innerHTML='<section class="shed-scene '+(r.key?'key-taken':'')+'"><header class="top"><div><b>農舍內部調查</b><br><small>找找看監視器的記憶卡是否被收在這裡。</small></div></header><button class="shed-hot drawer" onclick="c2Drawer()" aria-label="上鎖的抽屜"></button>'+(r.key?'':'<button class="shed-hot hook" onclick="c2Key()" aria-label="牆上掛鉤的小鑰匙"></button>')+'</section>'};
  window.c2Drawer=function(){if(!runtime().key){showModal('<h2>上鎖的抽屜</h2><p>抽屜鎖住了。</p><button class="primary" onclick="c2ShedSearch()">關閉</button>');return}showModal('<h2>上鎖的抽屜</h2><p>手上的小鑰匙似乎可以打開它。</p><button class="primary" onclick="c2CardFound()">使用鑰匙</button>')};window.c2Key=function(){showModal('<h2>發現物品</h2><p>掛鉤上有一把小鑰匙。</p><button class="primary" onclick="c2TakeKey()">取下鑰匙</button>')};window.c2TakeKey=function(){runtime().key=true;clearModal();window.c2ShedSearch()};
  window.c2CardFound=function(){showModal('<h2>發現物品</h2><p>抽屜裡放著一張記憶卡。</p><button class="primary" onclick="c2ReturnCamera()">取出記憶卡</button>')};window.c2ReturnCamera=function(){runtime().card=true;showModal('<p>這可能是監視器使用的記憶卡。</p><button class="primary" onclick="c2BackToCamera()">返回監視器</button>')};window.c2BackToCamera=function(){clearModal();drawExterior()};
  window.c2InsertCard=function(){showModal('<h2>農舍外牆監視器</h2>'+cameraFrame('記憶卡槽已確認')+'<p>你帶回了可能屬於這台監視器的記憶卡。</p><button class="primary" onclick="c2Timeline()">插入記憶卡</button>')};window.c2Timeline=function(){showModal('<h2>監視器錄影</h2>'+cameraFrame('資料讀取完成','ready')+'<p>00:47　　01:31　　<button class="choice" onclick="c2Video0213()">02:13・偵測到動態</button>　　03:26</p>')};
  window.c2Video0213=function(){showModal('<h2>02:13 錄影畫面</h2><img class="cctv-storyboard" src="assets/case2_cctv_0213_storyboard.png" alt="監視器依序拍到男子抱箱進入、打開箱子、把害蟲倒入小白菜田"><p class="frame-caption">① 抱著箱子進入農田　② 打開箱子　③ 將箱中害蟲倒入小白菜田</p><button class="primary" onclick="c2Compare()">放大人物</button>')};window.c2Compare=function(){showModal('<h2>人物比對</h2><img class="identity-compare" src="assets/case2_identity_compare.png" alt="左側監視器人物特寫，右側申請資料中的申請人照片"><div class="compare-captions"><span>監視器人物特寫</span><span>申請資料中的申請人照片</span></div><button class="primary" onclick="c2EvidenceFound()">比對</button>')};window.c2EvidenceFound=function(){showModal('<h2>身分吻合。</h2><p>監視器中的人物為本案申請人。</p><p>📹 監視器影像<br>申請人自行將害蟲放入農田。</p><button class="primary" onclick="c2Recheck()">返回審查室</button>')};

  window.c2Recheck=function(){showModal('<h2>重新審查</h2><p>原本查得的事實仍然成立：</p><p>✓ 作物是小白菜<br>✓ 確有蟲害<br>✓ 受損比例為32%</p><p>但是現在多了一項新證據：</p><p>📹 <b>監視器影像</b><br>申請人自行將害蟲放入農田。</p><button class="primary" onclick="c2ApprovalQuestion()">繼續</button>')};window.c2ApprovalQuestion=function(){showModal('<h2>知道這項新事實後，<br>你還會核准這筆補助嗎？</h2><button class="choice" onclick="c2ApprovalRetry()">A. 仍然核准</button><button class="choice" onclick="c2ReasonQuestion()">B. 改為不予核准</button>')};window.c2ApprovalRetry=function(){showModal('<p>如果只看表面的文字條件，他的確都符合。</p><p>但再想想：這些符合補助資格的條件，是怎麼形成的？</p><button class="primary" onclick="c2ApprovalQuestion()">重新判斷</button>')};
  window.c2ReasonQuestion=function(){showModal('<h2>真正需要重新考慮的原因是什麼？</h2><button class="choice" onclick="c2ReasonChoice(\'crop\')">A. 因為小白菜不屬於農作物</button><button class="choice" onclick="c2ReasonChoice(\'ratio\')">B. 因為受損比例其實不到20%</button><button class="choice" onclick="c2ReasonChoice(\'manufactured\')">C. 因為申請人故意製造取得補助的條件，再據此要求補助</button><button class="choice" onclick="c2ReasonChoice(\'human\')">D. 因為只要有人為因素，就一定不能申請補助</button>')};window.c2ReasonChoice=function(answer){if(answer==='manufactured'){window.c2Good();return}const hints={crop:'原本查得的作物確實是小白菜，這項事實沒有改變。注意新的監視器證據改變了什麼。',ratio:'原本查得的受損比例仍為32%，這項事實沒有改變。注意新的監視器證據改變了什麼。',human:'人為因素本身不是唯一判準；再想想申請人如何讓自己符合補助條件。'};showModal('<p>'+hints[answer]+'</p><button class="primary" onclick="c2ReasonQuestion()">再想想</button>')};
  window.c2Good=function(){showModal('<p>申請人故意製造取得補助的條件，再據此要求補助。</p><h2>這主要涉及哪一項法律原則？</h2><button class="choice" onclick="c2PrincipleChoice(\'equality\')">A. 平等原則</button><button class="choice" onclick="c2PrincipleChoice(\'proportionality\')">B. 比例原則</button><button class="choice" onclick="c2PrincipleChoice(\'goodFaith\')">C. 誠實信用原則</button><button class="choice" onclick="c2PrincipleChoice(\'clarity\')">D. 法律明確性原則</button>')};
  window.c2PrincipleChoice=function(answer){if(answer!=='goodFaith'){const hints={equality:'再想想：本題不是比較不同人民是否受到相同對待。注意申請人取得補助資格的方式。',proportionality:'再想想：本題不是國家限制人民權利是否過度。注意補助資格條件是怎麼形成的。',clarity:'再想想：規定的文字已經寫明補助條件；本題要看申請人如何讓自己符合這些條件。'};showModal('<p>'+hints[answer]+'</p><button class="primary" onclick="c2Good()">再想想</button>');return}showModal('<h2>🤝 誠實信用原則</h2><p>申請人確實符合表面的文字條件：</p><p>小白菜、<br>有蟲害、<br>受損32%。</p><p>但是，他故意製造取得補助的條件，再據此要求補助。</p><p>法律不能只看文字表面。<br>有權解釋、適用法規的機關，在個案中仍應依誠實信用原則解釋與適用規定。</p><p>符合文字，不一定就是法律適用的終點。</p><button class="primary" onclick="c2End()">完成案件二</button>')};
  window.c2End=function(){showModal('<h2>CASE 02 CLOSED</h2><p>表面文字條件雖成立，但條件是申請人故意製造，產生誠實信用原則的問題。</p><button class="primary" onclick="finish(\'c2\')">結案</button>')};
})();
